/* @author MILO-GAO(高振銘)@2020 */ package page2020.core;import java.util.ArrayList;import java.util.Arrays;import java.util.List;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.util.StringUtils;import page2020.View;import page2020.flow.Personal;import page2020.unit.Icon;import page2020.unit.Icon.ValueOfSize;import page2020.util.EmptyUtil;import page2020.view.B4;import page2020.view.C3;import page2020.view.Content;import page2020.view.Element;import page2020.view.H5;import page2020.view.Tag;import page2020.view.bs4.B4element;import page2020.view.bs4.B4show.D;import page2020.view.css3.C3bg;public class Page extends View {	public static Logger log = LoggerFactory.getLogger(Page.class);	private Personal personal;	private App app;	private List<Icon> icons = new ArrayList<Icon>();	private String styleE;	private String scriptE;	private String[] logo = new String[3];	private String zoom = "75%";	private String searchTipCode = null;	private String[] fontFamily;	private String backColor;	private String backImage;	private String barColor;	private String barBg;	private String barActive;	private String headerColor;	private String bodyColor;	private String[] langs = null;	private int ui;	public Page personal(Personal personal) {		this.personal = personal;		return this;	}	public Page icon(String x32, String x192, String x180) {		if (EmptyUtil.not(x32, x192, x180)) {			this.icons.clear();			this.icons.add(new Icon(Path.icons + x32, ValueOfSize.icon32));			this.icons.add(new Icon(Path.icons + x192, ValueOfSize.icon192));			this.icons.add(new Icon(Path.icons + x180, ValueOfSize.apple));		} else {			log.error("icon: argument(x32, x192, x180) has empty !");		}		return this;	}	public Page logo(String small, String medium, String large) {		if (EmptyUtil.not(small, medium, large)) {			this.logo[0] = Path.icons + small;			this.logo[1] = Path.icons + medium;			this.logo[2] = Path.icons + large;		} else {			log.error("logo: argument(small, medium, large) has empty !");		}		return this;	}	public Page color(String bar, String background, String color, String active) {		if (EmptyUtil.not(bar, background, color, active)) {			this.barBg = bar;			this.barColor = color;			this.barActive = active;			this.backColor = background;			super.css(C3.bg(background));		} else {			log.error("color: argument(bar, background, color, active) has empty !");		}		return this;	}	public Page backColor(String color) {		if (EmptyUtil.not(color)) {			this.backColor = color;			super.css(C3.bg(color));		} else {			log.error("backColor: argument(color) is empty !");		}		return this;	}	public Page backImage(String path) {		if (EmptyUtil.not(path)) {			this.backImage = path;			super.css(C3.bg.image(Name.Path.icons + path));			super.css(C3.bg.size(C3bg.Size.cover));		} else {			log.error("backImage: argument(path) is empty !");		}		return this;	}	public Page header(String color) {		if (EmptyUtil.not(color)) {			this.headerColor = color;		} else {			log.error("header: argument(color) is empty !");		}		return this;	}	public Page body(String color) {		if (EmptyUtil.not(color)) {			this.bodyColor = color;		} else {			log.error("body: argument(color) is empty !");		}		return this;	}	public Page font(String... families) {		if (EmptyUtil.not(families)) {			this.fontFamily = families;			super.css(C3.font.family(families));		} else {			log.error("font: argument(families) is empty !");		}		return this;	}	public Page zoom(double ratio) {		int zoom = (int) (100.0 * ratio);		if (zoom >= 10 && zoom <= 100) {			this.zoom = String.valueOf(zoom) + "%";		} else {			log.error("radio: argument(zoom) is out of range !");		}		return this;	}	public Page search(String searchTipCode) {		this.searchTipCode = searchTipCode;		return this;	}	public Page langs(String... langs) {		if (EmptyUtil.not(langs)) {			this.langs = langs;		}		return this;	}	public Page begin(App app) {		this.app = app;		super.setPath(Path.app + app.getSysCode() + "/");		super.data("app", app.getName());		super.data("cls", app.getClsCode());		super.data("sys", app.getSysCode());		super.data("code", app.getAppCode());		if (Log.view) {			log.info(app.getName()				+ " : icon=" + this.icons.size()				+ ", logo=" + Arrays.asList(this.logo).toString()				+ ", search='" + this.searchTipCode + "'"				+ ", bar-color=" + this.barColor + ", " + this.barBg + ", " + this.barActive				+ ", back-color=" + this.backColor + " (" + this.backImage + ")");		}		return this;	}	public Page end(View view) {		Page sysPage = App.page(this.app.getSysCode());		super.merge(sysPage);		if ((Element<?, ?>) super.find(null, "main", null) == null) {			super.cssClass("p-3");		}		if (view.getButtons().size() > 0) {			B4element element = B4.element();			view.getButtons().forEach((btnName, button) -> element.append(button));			view.getButtons().clear();			super.append(element);		}		super.merge(view);		if (view.count() > 0) {			super.append(view.getContents());			view.empty();		}		if (Log.view) {						log.info(this.app.getName()				+ " : equivs=" + super.getEquivs().size()				+ ", stylesheet=" + super.getStylesheets().size()				+ ", script=" + super.getScripts().size()				+ ", selector=" + super.getSelector().count()				+ ", javascripts=" + super.getJavascripts());		}		return this;	}	public Personal personal() {		return this.personal;	}	@Override	public boolean replace(Content<?> origin, List<Content<?>> newList) {		if (super.replace(origin, newList)) {			if (origin instanceof Tag<?>) {				((Tag<?>) origin).build();				}			return true;		}		return false;	}	@Override	public void build() {		if (super.getSelector().count() > 0) {			List<String> selectors = new ArrayList<String>();			super.getSelector().getData().forEach((name, map) -> {				List<String> styles = new ArrayList<String>();				map.forEach((key, value) -> styles.add(String.format("%s:%s;", key, value)));				selectors.add(String.format("%s {%s}", name,					StringUtils.collectionToDelimitedString(styles, " ")));			});			this.styleE = StringUtils.collectionToDelimitedString(selectors, " ");		}		if (super.getJavascripts().size() > 0) {			this.scriptE = StringUtils.collectionToDelimitedString(super.getJavascripts(), " ");		}		if (! super.getMessages().isEmpty()) {			B4element element = B4.element().cssClass(D.none).data("message", "page2020");			super.getMessages().forEach(code -> element.append(H5.span().data("code", code).code(code)));			super.append(element);				}		super.build();	}	@Override	public Page copy() {		Page bean = (Page) super.copy();		bean.setIcons(new ArrayList<Icon>());		this.icons.forEach(icon -> bean.getIcons().add(icon.copy()));		bean.setLogo(Arrays.copyOf(this.logo, 3));		if (this.fontFamily != null) {			bean.setFontFamily(Arrays.copyOf(this.fontFamily, this.fontFamily.length));		}		return bean;	}	public Personal getPersonal() {		return personal;	}	public void setPersonal(Personal personal) {		this.personal = personal;	}	public App getApp() {		return app;	}	public void setApp(App app) {		this.app = app;	}	public List<Icon> getIcons() {		return icons;	}	public void setIcons(List<Icon> icons) {		this.icons = icons;	}	public String getStyleE() {		return styleE;	}	public void setStyleE(String styleE) {		this.styleE = styleE;	}	public String getScriptE() {		return scriptE;	}	public void setScriptE(String scriptE) {		this.scriptE = scriptE;	}	public String[] getLogo() {		return logo;	}	public void setLogo(String[] logo) {		this.logo = logo;	}	public String getZoom() {		return zoom;	}	public void setZoom(String zoom) {		this.zoom = zoom;	}	public String getSearchTipCode() {		return searchTipCode;	}	public void setSearchTipCode(String searchTipCode) {		this.searchTipCode = searchTipCode;	}	public String[] getFontFamily() {		return fontFamily;	}	public void setFontFamily(String[] fontFamily) {		this.fontFamily = fontFamily;	}	public String getBackColor() {		return backColor;	}	public void setBackColor(String backColor) {		this.backColor = backColor;	}	public String getBackImage() {		return backImage;	}	public void setBackImage(String backImage) {		this.backImage = backImage;	}	public String getBarColor() {		return barColor;	}	public void setBarColor(String barColor) {		this.barColor = barColor;	}	public String getBarBg() {		return barBg;	}	public void setBarBg(String barBg) {		this.barBg = barBg;	}	public String getBarActive() {		return barActive;	}	public void setBarActive(String barActive) {		this.barActive = barActive;	}	public String getHeaderColor() {		return headerColor;	}	public void setHeaderColor(String headerColor) {		this.headerColor = headerColor;	}	public String getBodyColor() {		return bodyColor;	}	public void setBodyColor(String bodyColor) {		this.bodyColor = bodyColor;	}	public String[] getLangs() {		return langs;	}	public void setLangs(String[] langs) {		this.langs = langs;	}	public int getUi() {		return ui;	}	public void setUi(int ui) {		this.ui = ui;	}}